package org.sleepwell.app;
import android.content.Context;import java.io.*;import java.util.*;import java.util.concurrent.Semaphore;
/** Private staging, exclusively owned through actual close. No shared/public signal files. */
final class ResearchWorkspace implements AutoCloseable {
 private static final Semaphore OWNER=new Semaphore(1);final File directory;private boolean closed;
 private ResearchWorkspace(File directory){this.directory=directory;}
 static ResearchWorkspace create(Context app)throws IOException{if(!OWNER.tryAcquire())throw new IOException("Another signal export is still closing.");try{File cache=app.getCacheDir().getCanonicalFile(),root=new File(cache,"research-signal-exports").getCanonicalFile();if(!cache.equals(root.getParentFile())||!root.isDirectory()&&!root.mkdirs())throw new IOException("Private signal export storage unavailable.");File[] stale=root.listFiles();if(stale==null||stale.length>128)throw new IOException("Private signal export cleanup needs attention.");for(File old:stale)if(old.getName().matches("export-[0-9a-f-]{36}"))remove(root,old);File directory=new File(root,"export-"+UUID.randomUUID());if(!directory.mkdir())throw new IOException("Private signal export storage unavailable.");return new ResearchWorkspace(directory);}catch(IOException|RuntimeException error){OWNER.release();throw error;}}
 File file(String name)throws IOException{if(closed||!name.equals("manifest.json")&&!name.matches("night-[0-9a-f-]{36}\\.jsonl"))throw new IOException("Invalid private signal entry.");File file=new File(directory,name).getCanonicalFile();if(!directory.getCanonicalFile().equals(file.getParentFile()))throw new IOException("Invalid private signal entry.");return file;}
 private static void remove(File root,File directory)throws IOException{if(!directory.getCanonicalFile().equals(directory.getAbsoluteFile())||!root.equals(directory.getCanonicalFile().getParentFile())||!directory.isDirectory())throw new IOException("Invalid private signal export folder.");File[] files=directory.listFiles();if(files==null||files.length>ResearchSignals.MAX_NIGHTS+1)throw new IOException("Private signal export cleanup needs attention.");for(File file:files){String name=file.getName();if(!name.equals("manifest.json")&&!name.matches("night-[0-9a-f-]{36}\\.jsonl")||!file.getCanonicalFile().equals(file.getAbsoluteFile())||!file.getParentFile().getCanonicalFile().equals(directory.getCanonicalFile())||!file.isFile()||!file.delete())throw new IOException("Private signal export cleanup needs attention.");}if(!directory.delete())throw new IOException("Private signal export cleanup needs attention.");}
 public void close()throws IOException{if(closed)return;closed=true;try{remove(directory.getParentFile(),directory);}finally{OWNER.release();}}
}
